const ARCHIVE_SKIP = Symbol("archive-skip");
const ARCHIVE_INVALID_RECORD = "INVALID_RECORD";

function archiveIsBlankLine(text) {
  return text.trim() === "";
}

function archiveParseLine(text, line) {
  if (archiveIsBlankLine(text)) {
    return ARCHIVE_SKIP;
  }

  try {
    return JSON.parse(text);
  } catch (error) {
    if (!(error instanceof SyntaxError)) {
      error = new SyntaxError("Invalid JSON record");
    }
    error.code = ARCHIVE_INVALID_RECORD;
    error.line = line;
    throw error;
  }
}

async function* readArchive(chunks) {
  let source;
  let sourceAcquired = false;
  let sourceDone = false;
  let sourceCloseStarted = false;
  let failed = false;

  try {
    source = chunks[Symbol.asyncIterator]();
    sourceAcquired = true;

    const decoder = new TextDecoder();
    let pendingText = "";
    let pendingOffset = 0;
    let lineParts = [];
    let lineNumber = 1;

    while (true) {
      let value;

      while (true) {
        const newlineIndex = pendingText.indexOf("\n", pendingOffset);

        if (newlineIndex !== -1) {
          if (newlineIndex > pendingOffset) {
            lineParts.push(
              pendingText.slice(pendingOffset, newlineIndex)
            );
          }

          pendingOffset = newlineIndex + 1;

          if (pendingOffset === pendingText.length) {
            pendingText = "";
            pendingOffset = 0;
          }

          let lineText = lineParts.join("");
          lineParts = [];

          if (
            lineText.length > 0 &&
            lineText.charCodeAt(lineText.length - 1) === 0x0d
          ) {
            lineText = lineText.slice(0, -1);
          }

          const parsed = archiveParseLine(lineText, lineNumber);
          lineNumber += 1;

          if (parsed === ARCHIVE_SKIP) {
            continue;
          }

          value = parsed;
          break;
        }

        if (pendingOffset < pendingText.length) {
          lineParts.push(pendingText.slice(pendingOffset));
          pendingText = "";
          pendingOffset = 0;
        }

        if (sourceDone) {
          if (lineParts.length === 0) {
            return;
          }

          const lineText = lineParts.join("");
          lineParts = [];

          const parsed = archiveParseLine(lineText, lineNumber);
          lineNumber += 1;

          if (parsed === ARCHIVE_SKIP) {
            continue;
          }

          value = parsed;
          break;
        }

        const result = await source.next();

        if (result.done) {
          sourceDone = true;
          pendingText = decoder.decode();
        } else {
          pendingText = decoder.decode(result.value, { stream: true });
        }

        pendingOffset = 0;
      }

      yield value;
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (
      sourceAcquired &&
      !sourceDone &&
      !sourceCloseStarted
    ) {
      sourceCloseStarted = true;

      try {
        const returnMethod = source.return;

        if (typeof returnMethod === "function") {
          await returnMethod.call(source);
        }
      } catch (error) {
        if (!failed) {
          throw error;
        }
      }
    }
  }
}
